import heapq

def match(orders):
    trades = []
    book = {}  # id -> [side, price, qty, seq, active]
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq = 0

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                book[oid][4] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        else:  # market
            _, oid, side, qty = o
            price = None

        seq += 1
        remaining = qty

        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            top = heap[0]
            if side == 'buy':
                p = top[0]
            else:
                p = -top[0]
            topid = top[2]

            if topid not in book or not book[topid][4] or book[topid][2] <= 0:
                heapq.heappop(heap)
                continue

            if typ != 'market':
                if side == 'buy' and p > price:
                    break
                if side == 'sell' and p < price:
                    break

            avail = book[topid][2]
            trade_qty = min(remaining, avail)

            if side == 'buy':
                trades.append([oid, topid, p, trade_qty])
            else:
                trades.append([topid, oid, p, trade_qty])

            remaining -= trade_qty
            book[topid][2] -= trade_qty

            if book[topid][2] == 0:
                book[topid][4] = False
                heapq.heappop(heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = [side, price, remaining, seq, True]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        elif typ == 'limit':
            # fully filled, still record in book as inactive for cancel safety
            book[oid] = [side, price, 0, seq, False]

    return trades

